(()=>{'use strict';const D={"ko": {"briefing": {"title": "금리3.25%와 미래기금 심사, 미국장 휴장의 아침", "intro": "성장전망이 높아진 날 금리도 올랐다. 국회에서는 미래대응기금 심사가 보류됐고, 공공주택 모집 확대는 실제 입주와 다른 달력을 가리켰다. 미국26일 증시는 추수감사절로 쉬었다. 오늘은 큰 숫자보다 그 숫자가 가리키는 단계부터 확인한다. 이 브리핑은 아래에 연결한 개별 기사와 공개 근거를 요약한 것으로 낭독 대본이 아니다.", "href": "2026-11-27-morning-briefing-ko.html"}, "history": {"title": "유언 한 장은 어떻게 세계의 상이 되었나", "intro": "1895년 11월 27일, 알프레드 노벨은 파리의 스웨덴-노르웨이 클럽에서 세 번째이자 마지막 유언에 서명했다. 그날 노벨상이 수여된 것은 아니다. 유산을 어떤 목적에 쓸지 정한 문서가 남았을 뿐이었다. 첫 시상은 1901년 12월 10일에야 열렸다.", "href": "2026-11-27-nobel-will-ko.html"}}, "en": {"briefing": {"title": "A 3.25% rate, a deferred fund review and a US market holiday", "intro": "Interest rates rose on the day growth forecasts improved. Parliament deferred parts of the future-response fund review, and expanded public-housing recruitment followed a different calendar from move-in. US markets were closed for Thanksgiving on November 26. Today we ask which stage each large number describes. This briefing summarizes the linked articles and public evidence; it is not a read-aloud script.", "href": "2026-11-27-morning-briefing-en.html"}, "history": {"title": "How a will became a prize for the world", "intro": "On November 27, 1895, Alfred Nobel signed his third and final will at the Swedish-Norwegian Club in Paris. No Nobel Prize was awarded that day. What existed was a document directing the use of his estate. The first prizes were not awarded until December 10, 1901.", "href": "2026-11-27-nobel-will-en.html"}}, "ja": {"briefing": {"title": "金利3.25%と未来基金審査、米国休場の朝", "intro": "成長予測が上がった日に金利も上がった。国会では未来対応基金の一部審査が保留され、公共住宅の募集拡大は入居と違う日程を示した。米国26日の市場は感謝祭で休場だった。今日は大きな数字がどの段階を指すかから確認する。本稿は個別記事と公開根拠の要約であり、朗読台本ではない。", "href": "2026-11-27-morning-briefing-ja.html"}, "history": {"title": "一通の遺言は、どう世界の賞になったのか", "intro": "1895年11月27日、アルフレッド・ノーベルはパリのスウェーデン・ノルウェー・クラブで、3通目にして最後の遺言に署名した。その日にノーベル賞が授与されたわけではない。遺産の使い道を定めた文書が残されたのだ。初めての授賞は1901年12月10日だった。", "href": "2026-11-27-nobel-will-ja.html"}}, "zh": {"briefing": {"title": "3.25%利率、基金审议与美股休市的早晨", "intro": "增长预测上调当天，利率也上调。国会暂缓部分未来应对基金审议，公共住房招募增加也不同于入住日历。美国26日因感恩节休市。今天先问大数字描述哪个阶段。本简报汇总所连文章与公开依据，不是朗读稿。", "href": "2026-11-27-morning-briefing-zh.html"}, "history": {"title": "一份遗嘱如何成为面向世界的奖项", "intro": "1895年11月27日，阿尔弗雷德·诺贝尔在巴黎的瑞典挪威俱乐部签署了第三份，也是最后一份遗嘱。那天并没有颁发诺贝尔奖，留下的只是一份规定遗产用途的文件。首次颁奖直到1901年12月10日才举行。", "href": "2026-11-27-nobel-will-zh.html"}}, "es": {"briefing": {"title": "Tipo del 3,25%, fondo aplazado y festivo bursátil estadounidense", "intro": "Subieron los tipos el día que mejoraron las previsiones. El Parlamento aplazó parte del examen del fondo de respuesta al futuro, y ampliar convocatorias de vivienda no equivalió a adelantar mudanzas. EEUU cerró sus bolsas el 26 por Acción de Gracias. Hoy preguntamos qué etapa describe cada cifra. Este resumen recoge artículos enlazados y pruebas públicas, no es un guion de lectura.", "href": "2026-11-27-morning-briefing-es.html"}, "history": {"title": "Cómo un testamento se convirtió en un premio para el mundo", "intro": "El 27 de noviembre de 1895, Alfred Nobel firmó su tercer y último testamento en el Club Sueco-Noruego de París. Aquel día no se entregó ningún Premio Nobel. Existía un documento que indicaba cómo emplear su patrimonio. Los primeros premios no llegaron hasta el 10 de diciembre de 1901.", "href": "2026-11-27-nobel-will-es.html"}}};let last='';function sync(){const l=document.documentElement.dataset.lang||'ko';if(last===l)return;last=l;const q=D[l]||D.en;for(const [id,k] of [['daily-news-briefing','briefing'],['president-series-feature','history']]){const e=document.getElementById(id);if(!e)continue;const a=e.querySelector('h2 a');if(a){a.textContent=q[k].title;a.href=q[k].href}e.querySelectorAll('a').forEach(a=>{a.href=q[k].href;if(!a.closest('h2'))a.textContent=({ko:'전문 읽기 →',en:'Read full article →',ja:'全文を読む →',zh:'阅读全文 →',es:'Leer texto completo →'})[l]||'Read full article →';});const p=e.querySelector('p');if(p)p.textContent=q[k].intro;}}new MutationObserver(sync).observe(document.documentElement,{attributes:true,attributeFilter:['data-lang']});sync();})();